// =============================================
// KeybordStudio V1 - PCB manufacturing bundle
// modules/pcb/pcb-bundle.js
// =============================================
// 全 PCB 出力を 1 つの ZIP に詰めて、業者 (JLCPCB / PCBWay / Elecrow)
// にそのままアップロードできる形にする。
//
// JLCPCB ZIP 内容:
//   *.gtl, *.gbl                 (front/back copper)
//   *.gts, *.gbs                 (front/back solder mask)
//   *.gto, *.gbo                 (front/back silkscreen)
//   *.gtp, *.gbp                 (front/back paste)  ※SMD のみ
//   *.gko                        (board outline)
//   *-PTH.drl, *-NPTH.drl        (drill files)
//
// 別添 (BOM/CPL は通常別アップロードだが、参考用に同梱):
//   *-BOM.csv
//   *-PickAndPlace.csv
//   README.txt                   (board info, settings)
//   DRC-Report.txt               (DRC 結果ログ)
//
// JSZip はグローバル (index.html で <script> 読み込み済み)。

import { generateAllGerbers } from './pcb-gerber.js';
import { generateAllDrills }  from './pcb-drill.js';
import { generateAllBOM }     from './pcb-bom.js';
import { runDRC, formatDRC }  from './pcb-drc.js';

// ── README 生成 ──────────────────────────────
function buildReadme(meta, stats) {
    const lines = [];
    lines.push('=========================================');
    lines.push('  KeybordStudio v1 — PCB Manufacturing Pkg');
    lines.push('=========================================');
    lines.push('');
    lines.push(`Board name : ${meta.boardName || 'KeybordStudio_PCB'}`);
    lines.push(`Created    : ${new Date().toISOString()}`);
    lines.push(`Layers     : 2 (Top + Bottom)`);
    lines.push(`Thickness  : ${meta.thickness ?? 1.6} mm`);
    lines.push(`Color      : ${meta.color ?? 'Green'}`);
    lines.push(`Surface    : ${meta.surfaceFinish ?? 'HASL (lead-free)'}`);
    lines.push(`Min trace  : ${meta.minTrace ?? 0.20} mm`);
    lines.push(`Min hole   : ${meta.minDrill ?? 0.30} mm`);
    lines.push('');
    if (stats) {
        lines.push('-- Stats --');
        if (stats.board) {
            lines.push(`Size       : ${stats.board.width}×${stats.board.height} mm`);
        }
        if (stats.gerber)    lines.push(`Gerber     : ${stats.gerber} layers`);
        if (stats.drillPth)  lines.push(`Holes PTH  : ${stats.drillPth}`);
        if (stats.drillNpth) lines.push(`Holes NPTH : ${stats.drillNpth}`);
        if (stats.components) lines.push(`Components : ${stats.components}`);
        lines.push('');
    }
    lines.push('-- Vendor upload notes --');
    lines.push('JLCPCB:  Upload this entire ZIP via "Add Gerber file".');
    lines.push('         BOM/CPL CSV は SMT Assembly タブで別アップロード推奨。');
    lines.push('PCBWay:  ZIP をそのままアップロード。');
    lines.push('Elecrow: ZIP をアップロード。SMD 組み立ては別注文。');
    lines.push('');
    lines.push('Generated by KeybordStudio v1');
    lines.push('https://github.com/hololocheck/keybordstudio');
    return lines.join('\r\n') + '\r\n';
}

// ── メイン: ZIP 生成 ─────────────────────────
/**
 * PCB データから業者発注用 ZIP を作成して Blob を返す。
 *
 * @param {object} pcbData {
 *   meta:   { boardName, thickness, color, surfaceFinish, minTrace, minDrill },
 *   layers: { 'F.Cu': {pads:[], traces:[], lines:[], texts:[], polygons:[]}, ... },
 *   holes:  [...],
 *   vias:   [...],
 *   components: [...],
 *   board:  { width, height },
 *   nets?:  [...]
 * }
 * @param {object} options { includeBOM, includeDRC, drcVendor, includeReadme }
 * @returns {Promise<{blob:Blob, fileName:string, drc:object, files:string[]}>}
 */
export async function generateManufacturingBundle(pcbData, options = {}) {
    if (typeof JSZip === 'undefined') {
        throw new Error('JSZip is not loaded — bundle generation requires JSZip global.');
    }
    const opts = Object.assign({
        includeBOM:     true,
        includeDRC:     true,
        drcVendor:      'jlcpcb',
        includeReadme:  true
    }, options);

    const zip = new JSZip();
    const meta = pcbData.meta || {};
    const baseName = (meta.boardName || 'KeybordStudio_PCB').replace(/[\\/:*?"<>|]/g, '_');

    const files = [];
    const stats = {};

    // ── Gerber ────────────────────────────────
    const gerbers = generateAllGerbers(pcbData);
    for (const [fname, text] of Object.entries(gerbers)) {
        zip.file(fname, text);
        files.push(fname);
    }
    stats.gerber = Object.keys(gerbers).length;

    // ── Drill ─────────────────────────────────
    const drills = generateAllDrills(pcbData);
    for (const [fname, text] of Object.entries(drills)) {
        zip.file(fname, text);
        files.push(fname);
    }
    stats.drillPth  = (pcbData.holes || []).filter(h => h.plated !== false).length
                    + (pcbData.vias  || []).length;
    stats.drillNpth = (pcbData.holes || []).filter(h => h.plated === false).length;

    // ── BOM / Pick&Place ──────────────────────
    if (opts.includeBOM) {
        const boms = generateAllBOM(pcbData);
        for (const [fname, text] of Object.entries(boms)) {
            zip.file(fname, text);
            files.push(fname);
        }
        stats.components = (pcbData.components || []).length;
    }

    // ── DRC report ────────────────────────────
    let drcResult = null;
    if (opts.includeDRC) {
        drcResult = runDRC(pcbData, { vendor: opts.drcVendor });
        const drcText = formatDRC(drcResult);
        const drcName = `${baseName}-DRC.txt`;
        zip.file(drcName, drcText);
        files.push(drcName);
    }

    // ── README ────────────────────────────────
    if (opts.includeReadme) {
        if (pcbData.board) stats.board = pcbData.board;
        const readme = buildReadme(meta, stats);
        zip.file('README.txt', readme);
        files.push('README.txt');
    }

    // ── Generate blob ─────────────────────────
    const blob = await zip.generateAsync({
        type: 'blob',
        compression: 'DEFLATE',
        compressionOptions: { level: 6 }
    });

    return {
        blob,
        fileName: `${baseName}-manufacturing.zip`,
        drc:      drcResult,
        files,
        stats
    };
}

/**
 * 結果の Blob をブラウザでダウンロードさせるヘルパー。
 */
export function downloadBundle(bundle) {
    const url = URL.createObjectURL(bundle.blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = bundle.fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export default generateManufacturingBundle;
